-- Test scripts generated by the Test Script Agent while a Request is executing (docs/integrate/TDD-REQ-TESTSCRIPT-001). One row per
-- attempt; is_current = 1 marks the one the screen shows. Neither the code lane nor the test-spec lane reads it.
CREATE TABLE request_test_script_runs (
    id CHAR(36) PRIMARY KEY,
    tenant_id CHAR(36) NOT NULL,
    request_id CHAR(36) NOT NULL,
    attempt INT NOT NULL DEFAULT 1,
    status VARCHAR(16) NOT NULL CHECK (status IN ('pending','running','completed','needs_review','blocked','failed','skipped','cancelled')),
    reason_code VARCHAR(96) NOT NULL DEFAULT '',
    reason_message TEXT NOT NULL,
    test_spec_run_id VARCHAR(36) NOT NULL DEFAULT '',
    feature VARCHAR(128) NOT NULL DEFAULT '',
    spec_version INT NOT NULL DEFAULT 0,
    tsa_job_id VARCHAR(64) NOT NULL DEFAULT '',
    branch VARCHAR(255) NOT NULL DEFAULT '',
    base_ref VARCHAR(255) NOT NULL DEFAULT '',
    worktree_path VARCHAR(1024) NOT NULL DEFAULT '',
    commit_sha VARCHAR(64) NOT NULL DEFAULT '',
    summary JSON NOT NULL,
    started_by CHAR(36) NULL,
    started_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    finished_at TIMESTAMP(6) NULL,
    updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    is_current TINYINT NULL,
    superseded_at TIMESTAMP(6) NULL,
    lease_owner VARCHAR(255) NOT NULL DEFAULT '',
    lease_until TIMESTAMP(6) NOT NULL DEFAULT '2000-01-01 00:00:01.000000',
    CONSTRAINT fk_request_test_script_runs_request FOREIGN KEY (request_id) REFERENCES requests(id),
    UNIQUE KEY request_test_script_runs_one_current (tenant_id, request_id, is_current),
    INDEX request_test_script_runs_history (tenant_id, request_id, attempt),
    INDEX request_test_script_runs_active (status, updated_at)
) ENGINE=InnoDB;
